# Explorer parity fixtures, generated by calling the ORIGINAL R/analysis.R functions
# on the rebuilt bundle (build/r-work/explorer). Run after parity/r/run_explorer.sh:
#   source tools/env.sh; Rscript --vanilla parity/r/explorer_fixtures.R
# Batches are cached in build/r-work/explorer_fixtures/, so an interrupted run resumes.

Sys.setenv(TZ = "America/Toronto")
root <- normalizePath(Sys.getenv("TCA_ROOT", getwd()))
work <- file.path(root, "build", "r-work", "explorer")
out <- file.path(root, "parity", "r_outputs", "explorer")
cache <- file.path(root, "build", "r-work", "explorer_fixtures")
dir.create(cache, showWarnings = FALSE, recursive = TRUE)
setwd(work)
source("R/analysis.R")
bundle <- readRDS("data/processed/crime.rds")
events <- bundle$events
FIXTURE_SEED <- 303313L
N_RANDOM <- 2000L
BATCH <- 250L

presets <- c("all", "midterm", "final", "break_time", "peak", "off_peak")
radii <- c(100, 300, 500, 1000, 1100, 1200, 2000)
weekday_sets <- list(all = 1:7, mon_fri = 1:5, sat_sun = 6:7, mon = 1L)
hour_sets <- list(h0_23 = c(0, 23), h6_9 = c(6, 9), h19_23 = c(19, 23), h7_7 = c(7, 7))
cat_sets <- list(
  bicycle = "Bicycle theft", robbery = "Robbery", theft_over = "Theft over",
  bicycle_robbery = c("Bicycle theft", "Robbery"), bicycle_theft_over = c("Bicycle theft", "Theft over"),
  robbery_theft_over = c("Robbery", "Theft over"), all = crime_categories)
full_range <- range(events$date)
date_sets <- list(full = full_range,
                  apr_2023 = as.Date(c("2023-04-01", "2023-04-03")),
                  y2021 = as.Date(c("2021-01-01", "2021-12-31")))
place_ids <- bundle$places$id
modes <- c("destination", "station", "none")

make_case <- function(mode, place, radius, preset, wd, hr, cat, dr) {
  list(mode = mode, place = place, radius = radius, preset = preset, weekdays = wd,
       hours = hr, categories = cat, dates = dr)
}
default_case <- function(mode, place = place_ids[1], radius = 300, preset = "all", wd = "all",
                         hr = "h0_23", cat = "all", dr = "full") {
  make_case(mode, place, radius, preset, wd, hr, cat, dr)
}

# Deterministic case list: structured sweeps first, then a seeded random sample of the grid.
fixed <- list()
for (m in c("destination", "station")) for (p in place_ids) {
  fixed[[length(fixed) + 1]] <- default_case(m, p)
  for (r in radii) fixed[[length(fixed) + 1]] <- default_case(m, p, radius = r)
  for (pr in presets) fixed[[length(fixed) + 1]] <- default_case(m, p, preset = pr)
}
for (ct in names(cat_sets)) for (dn in names(date_sets)) for (pr in presets)
  fixed[[length(fixed) + 1]] <- default_case("none", cat = ct, dr = dn, preset = pr)
for (wn in names(weekday_sets)) for (hn in names(hour_sets))
  fixed[[length(fixed) + 1]] <- default_case("none", wd = wn, hr = hn)
# Empty selections must be handled identically (no categories, no weekdays).
fixed[[length(fixed) + 1]] <- default_case("none", cat = "empty")
fixed[[length(fixed) + 1]] <- default_case("none", wd = "empty")
fixed[[length(fixed) + 1]] <- default_case("destination", wd = "empty")

set.seed(FIXTURE_SEED)
random <- lapply(seq_len(N_RANDOM), function(i) {
  make_case(sample(modes, 1), sample(place_ids, 1), sample(radii, 1), sample(presets, 1),
            sample(names(weekday_sets), 1), sample(names(hour_sets), 1),
            sample(names(cat_sets), 1), sample(names(date_sets), 1))
})
cases <- c(fixed, random)
# The first 100 cases on the three-day range keep full arrays and CSV text for debugging.
is_apr <- vapply(cases, function(x) x$dates == "apr_2023", logical(1))
debug_ids <- head(which(is_apr), 100L)

canon <- function(d, extra = NULL) {
  fmt <- function(v) ifelse(is.na(v), "NA", sprintf("%.0f", v))
  cols <- list(format(d$date), d$category, fmt(d$count))
  if (!is.null(extra)) cols <- c(cols, list(fmt(extra)))
  paste(do.call(paste, c(cols, sep = "|")), collapse = "\n")
}
sha <- function(txt) digest::digest(txt, algo = "sha256", serialize = FALSE)
counts_vec <- function(x) lapply(x, function(v) if (is.na(v)) NULL else v)

run_case <- function(i) {
  cs <- cases[[i]]
  cats <- if (identical(cs$categories, "empty")) character() else cat_sets[[cs$categories]]
  wds <- if (identical(cs$weekdays, "empty")) integer() else weekday_sets[[cs$weekdays]]
  hrs <- hour_sets[[cs$hours]]
  dr <- date_sets[[cs$dates]]
  site <- bundle$places[bundle$places$id == cs$place, , drop = FALSE]
  center <- switch(cs$mode, destination = site, station = nearest_station(site, bundle$stations), none = NULL)
  sel <- filter_events(events, dr, cats, cs$preset, wds, hrs, center, cs$radius)
  daily <- daily_counts(sel, dr, cats, cs$preset, wds, hrs)
  trend <- function(interval) {
    d <- trend_counts(daily, interval)
    if (interval == "day") d$eligible_days <- as.integer(!is.na(d$count))
    d
  }
  week <- trend("week"); month <- trend("month"); day <- trend("day")
  d <- daily
  d$scope <- rep(if (is.null(center)) "All supplied locations" else center$name, nrow(d))
  d$radius_m <- rep(if (is.null(center)) NA_real_ else cs$radius, nrow(d))
  d$time_preset <- rep(cs$preset, nrow(d))
  d$selected_weekdays <- rep(paste(wds, collapse = ","), nrow(d))
  d$selected_hours <- rep(paste(hrs, collapse = "-"), nrow(d))
  tmp <- tempfile(fileext = ".csv")
  utils::write.csv(d, tmp, row.names = FALSE, na = "")
  csv <- readChar(tmp, file.size(tmp), useBytes = TRUE)
  unlink(tmp)
  res <- list(
    id = i,
    input = list(mode = cs$mode, place = if (cs$mode == "none") NULL else cs$place,
                 station = if (cs$mode == "station") center$id else NULL,
                 radius_m = cs$radius, preset = cs$preset, weekdays = wds, hours = hrs,
                 categories = cats, date_from = format(dr[1]), date_to = format(dr[2])),
    records = nrow(sel), distinct_ids = length(unique(sel$event_id)),
    ids_sha256 = sha(paste(sel$event_id, collapse = "\n")),
    by_category = as.integer(table(factor(sel$category, levels = crime_categories))),
    by_weekday = as.integer(table(factor(sel$weekday, levels = 1:7))),
    by_hour = as.integer(table(factor(sel$hour, levels = 0:23))),
    daily_rows = nrow(daily), daily_na = sum(is.na(daily$count)),
    daily_sha256 = sha(canon(daily)),
    day_sha256 = sha(canon(day, day$eligible_days)),
    week_sha256 = sha(canon(week, week$eligible_days)),
    month_sha256 = sha(canon(month, month$eligible_days)),
    csv_sha256 = sha(csv))
  if (i %in% debug_ids) {
    res$debug <- list(daily = counts_vec(daily$count), week = counts_vec(week$count),
                      week_eligible = week$eligible_days, month = counts_vec(month$count),
                      month_eligible = month$eligible_days, csv = csv)
  }
  res
}

batches <- split(seq_along(cases), ceiling(seq_along(cases) / BATCH))
results <- list()
for (b in names(batches)) {
  f <- file.path(cache, sprintf("batch_%03d.rds", as.integer(b)))
  if (!file.exists(f)) {
    r <- parallel::mclapply(batches[[b]], run_case, mc.cores = 4, mc.set.seed = FALSE)
    bad <- vapply(r, function(x) inherits(x, "try-error") || is.null(x), logical(1))
    if (any(bad)) stop("Fixture batch ", b, " failed for cases: ", paste(batches[[b]][bad], collapse = ","))
    saveRDS(r, f)
    cat("batch", b, "of", length(batches), "done\n")
  }
  results <- c(results, readRDS(f))
}

# Named exact checks from VALIDATION.md and the plan, computed from the same functions.
validation <- list(
  little_canada_300m = {
    x <- filter_events(events, full_range, center = bundle$places[bundle$places$id == "site1", ], radius_m = 300)
    list(records = nrow(x), distinct_ids = length(unique(x$event_id)))
  },
  dundas_station_300m = {
    st <- nearest_station(bundle$places[bundle$places$id == "site1", ], bundle$stations)
    x <- filter_events(events, full_range, center = st, radius_m = 300)
    list(station = st$name, records = nrow(x), distinct_ids = length(unique(x$event_id)))
  },
  robbery_only_all_locations = list(records = nrow(filter_events(events, full_range, "Robbery"))))

# Smallest gap between any record's distance and a slider radius, per place and mode.
gaps <- do.call(rbind, lapply(c("destination", "station"), function(m) {
  do.call(rbind, lapply(place_ids, function(p) {
    site <- bundle$places[bundle$places$id == p, , drop = FALSE]
    ctr <- if (m == "station") nearest_station(site, bundle$stations) else site
    d <- haversine_m(events$longitude, events$latitude, ctr$longitude, ctr$latitude)
    data.frame(mode = m, place = p, min_gap_m = min(vapply(radii, function(r) min(abs(d - r)), numeric(1))))
  }))
}))

meta <- list(seed = FIXTURE_SEED, n_cases = length(cases), n_random = N_RANDOM,
             n_debug = length(debug_ids), full_range = format(full_range),
             events = nrow(events), validation = validation,
             min_radius_gap_m = min(gaps$min_gap_m),
             r_version = R.version.string, tz = "America/Toronto")
jsonlite::write_json(list(meta = meta, cases = results), file.path(out, "fixtures.json"),
                     auto_unbox = TRUE, null = "null", na = "null", digits = NA)

# Event table in R's row order with coordinates as exact hex doubles, plus config tables.
ev <- events
ev$longitude_hex <- sprintf("%a", ev$longitude)
ev$latitude_hex <- sprintf("%a", ev$latitude)
ev$date <- format(ev$date)
gz <- gzfile(file.path(out, "events_hex.csv.gz"), "w")
utils::write.csv(ev, gz, row.names = FALSE)
close(gz)
for (nm in c("places", "stations")) {
  x <- bundle[[nm]]
  x$longitude_hex <- sprintf("%a", x$longitude)
  x$latitude_hex <- sprintf("%a", x$latitude)
  utils::write.csv(x, file.path(out, paste0(nm, "_hex.csv")), row.names = FALSE)
}
jsonlite::write_json(bundle$manifest, file.path(out, "manifest.json"), auto_unbox = TRUE, digits = NA, pretty = TRUE)
writeLines(capture.output(sessionInfo()), file.path(out, "session_explorer.txt"))
cat("fixtures:", length(results), "cases;", format(file.size(file.path(out, "fixtures.json")) / 1e6, digits = 3), "MB\n")
print(validation)
